def verify_schema(schema_def: dict) -> list:
    """
    Verifies relational database schema invariants from a schema definition dictionary.

    Detects:
    1. Missing primary keys.
    2. Unindexed foreign key columns.
    3. Non-null constraint drift (if columns designated as non-null allow nulls, 
       or depending on interpretation, inconsistent definitions across relations).

    Expected format for schema_def:
    {
        "tables": {
            "table_name": {
                "columns": {
                    "column_name": {
                        "type": "INTEGER",
                        "nullable": False,  # True or False
                        "primary_key": True, # True or False (optional/explicit)
                        "foreign_key": "other_table.other_column" # Optional string or dict
                    },
                    ...
                },
                "indexes": [
                    ["col1"],
                    ["col2", "col3"],
                    ...
                ]
            },
            ...
        }
    }

    Returns a list of violation messages (strings).
    """
    violations = []

    tables = schema_def.get("tables", {})

    for table_name, table_info in tables.items():
        columns = table_info.get("columns", {})
        indexes = table_info.get("indexes", [])

        # Flatten indexes into a set of single columns and composite prefixes for easy lookup,
        # or just check if the leading column of an index matches the FK.
        # Standard DB index usage typically requires the FK column to be the *leading* 
        # column of at least one index. Let's collect all indexed columns/prefixes.
        indexed_prefixes = set()
        for idx in indexes:
            if idx:
                # Add the first column of the index, and any sequential prefixes
                for i in range(1, len(idx) + 1):
                    indexed_prefixes.add(tuple(idx[:i]))

        # Simple set of individually indexed columns
        individually_indexed = {idx[0] for idx in indexes if len(idx) > 0}

        has_primary_key = False

        for col_name, col_def in columns.items():
            # 1. Check Primary Keys
            if col_def.get("primary_key", False):
                has_primary_key = True

            # 3. Check Non-Null Constraint Drift
            # If a column is part of a primary key, it should typically be non-null.
            # "Non-null constraint drift" can also imply that a column expected to be non-null 
            # is marked as nullable: True, or inconsistencies in definition.
            if col_def.get("primary_key", False) and col_def.get("nullable", True):
                violations.append(
                    f"Table '{table_name}', column '{col_name}': Primary key column cannot be nullable."
                )

            # 2. Check Unindexed Foreign Keys
            # A foreign key can be defined via "foreign_key" key in column definition.
            fk = col_def.get("foreign_key")
            if fk:
                # Check if this column is indexed
                # An FK column should be the leading column of an index for optimal JOIN performance and locking.
                if col_name not in individually_indexed and (col_name,) not in indexed_prefixes:
                    violations.append(
                        f"Table '{table_name}', column '{col_name}': Foreign key is unindexed."
                    )

        # Check if table is missing a primary key
        if not has_primary_key:
            violations.append(
                f"Table '{table_name}' is missing a primary key."
            )

    return violations
